p.rep('Generated by Abyssal Cartographer v4.1. Dungeon code: ', 'Generated by Abyssal Cartographer v4.2. Dungeon code: ')
p.rep('Made with Abyssal Cartographer v4.1. ', 'Made with Abyssal Cartographer v4.2. ')

